steps.code_template:
# 결과 해석
print("=== 데이터 분석 결과 해석 ===")

# 분포의 대칭성 평가
if abs(mean_value - median_value) < std_dev * 0.1:
    print("분포가 대칭적입니다 (평균 ≈ 중앙값)")
elif mean_value > median_value:
    print("분포가 우측으로 치우쳐 있습니다 (평균 > 중앙값)")
else:
    print("분포가 좌측으로 치우쳐 있습니다 (평균 < 중앙값)")

# 변동성 평가
if cv < 15:
    print("데이터의 변동성이 낮습니다 (일관성 높음)")
elif cv < 30:
    print("데이터의 변동성이 보통입니다")
else:
    print("데이터의 변동성이 높습니다 (일관성 낮음)")

print(f"\n데이터 요약:")
print(f"- 중심값: 평균 {mean_value:.1f}, 중앙값 {median_value:.1f}")
print(f"- 변동성: 표준편차 {std_dev:.1f}, 변동계수 {cv:.1f}%")
print(f"- 범위: {data_range:.1f} (최소 {df['scores'].min():.1f} ~ 최대 {df['scores'].max():.1f})")
